Complete local Java example; the app itself does not execute it:
```java
import java.util.Objects;
interface Formatter { String format(String text); }
class Plain implements Formatter {
    public String format(String text) { return text; }
}
class Excited implements Formatter {
    public String format(String text) { return text + "!"; }
}
class NoticeService {
    private final Formatter formatter;
    NoticeService(Formatter formatter) {
        this.formatter = Objects.requireNonNull(formatter);
    }
    String message(String text) { return formatter.format(text); }
}
public class Main {
    public static void main(String[] args) {
        NoticeService service = new NoticeService(new Plain());
        System.out.println(service.message("Ready"));
    }
}

```

